using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor{
[InitializeOnLoad]public static class CoordinatedOrdersVerification{
 const string Key="CoordinatedOrdersVerification";static double start;static List<string> rows=new List<string>();
 static CoordinatedOrdersVerification(){if(SessionState.GetBool(Key,false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;}}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/DoubleValley9x.unity");SessionState.SetBool(Key,true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);rows.Add("PASS "+m);Debug.Log("COORD_PASS "+m);}
 static bool Visible(CampaignHUD h,string text){return h.GetComponentsInChildren<Button>(true).Any(b=>b.gameObject.activeSelf&&b.GetComponentInChildren<Text>()!=null&&b.GetComponentInChildren<Text>().text==text);}
 static void Test(BattleWorld w){w.enabled=false;foreach(var initial in w.units)if(initial!=null&&initial.Point!=null)initial.BeginExit();w.GetComponent<BattleAIController>().enabled=false;w.GetComponent<AIBasicCommander>().enabled=false;w.fogEnabled=false;w.SetPlayer("A");foreach(var u in w.units){u.Motor.Stop();u.transform.position=new Vector3(u.ownerId=="A"?-45:45,-27);}var svc=w.GetComponent<LocalCoordinatedOrders>();Check(svc!=null,"coordinated service installed offline");var hud=UnityEngine.Object.FindObjectOfType<CampaignHUD>();var blue=w.units.Where(u=>u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Infantry).ToArray();var front=blue[0];var rear=blue[1];var third=w.units.First(u=>u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Engineer);var enemy=w.units.First(u=>u.ownerId=="B"&&u.combatDefinition.role==UnitRole.Infantry);var roads=w.setup.roadMap;var edge=roads.definition.connections.OrderByDescending(e=>(roads.definition.nodes[e.a]-roads.definition.nodes[e.b]).sqrMagnitude).First();var p=roads.transform.TransformPoint(Vector2.Lerp(roads.definition.nodes[edge.a],roads.definition.nodes[edge.b],.3f));var q=roads.transform.TransformPoint(Vector2.Lerp(roads.definition.nodes[edge.a],roads.definition.nodes[edge.b],.7f));front.transform.position=p;rear.transform.position=q;hud.SelectUnit(front);Check(!Visible(hud,"取消轮换")&&!Visible(hud,"取消联防"),"unassociated unit has no cancellation buttons");
  svc.BeginPicking(LocalCoordinatedOrders.PickMode.Rotation);Check(svc.Pick(front)&&svc.Pick(rear),"E flow selects front then rear");Check(svc.InRotation(front)&&svc.InRotation(rear)&&svc.Picking==LocalCoordinatedOrders.PickMode.None,"rotation associates both units");Check(rear.Motor.IsMoving&&!front.Motor.IsMoving&&front.transform.position==p,"rear moves first and front holds");bool beganWithdrawal=false,frontHeld=true;for(int i=0;i<10000&&svc.InRotation(front);i++){rear.Motor.Tick(.2f);front.Motor.Tick(.2f);svc.Tick(.2f);if(!beganWithdrawal&&front.Motor.IsMoving){Check(Vector2.Distance(rear.transform.position,p)<.031f,"front withdraws only after rear reached front position");beganWithdrawal=true;}if(!beganWithdrawal)frontHeld&=Vector2.Distance(front.transform.position,p)<.001f;}Check(frontHeld,"front holds throughout rear approach");Check(beganWithdrawal&&!svc.InRotation(front)&&Vector2.Distance(front.transform.position,q)<.031f&&Vector2.Distance(rear.transform.position,p)<.031f,"rotation completes both original positions");
  front.transform.position=p;rear.transform.position=q;Check(svc.StartRotation(front,rear),"second rotation starts");hud.SelectUnit(front);Check(Visible(hud,"取消轮换"),"front member sees cancellation button");svc.CancelRotation(front);Check(!svc.InRotation(rear)&&!rear.Motor.IsMoving,"front cancellation stops whole pair");Check(svc.StartRotation(front,rear),"third rotation starts");svc.CancelRotation(rear);Check(!svc.InRotation(front)&&!rear.Motor.IsMoving,"rear cancellation stops whole pair");Check(svc.StartRotation(front,rear),"blocked rotation starts");rear.Motor.Stop();svc.Tick(.1f);Check(!svc.InRotation(front)&&front.transform.position==p,"interrupted rear movement cancels without premature retreat");
  third.transform.position=Vector3.Lerp(p,q,.7f);svc.BeginPicking(LocalCoordinatedOrders.PickMode.Defense);Check(svc.Pick(front)&&svc.Pick(rear)&&svc.Pick(third),"H supports several linked partners");svc.EndPicking();Check(svc.LinkCount(front)==2&&svc.LinkCount(rear)==1&&svc.LinkCount(third)==1,"multiple defense links registered");Check(svc.LinkDefense(front,rear)&&svc.LinkCount(front)==2,"duplicate association creates no duplicate link");Check(!svc.LinkDefense(front,enemy),"enemy cannot be linked");hud.SelectUnit(rear);Check(Visible(hud,"取消联防"),"linked member sees defense cancellation");
  w.NotifyUnitHit(front,"A",rear);svc.Tick(.1f);Check(!svc.Supporting(third),"friendly damage does not summon support");enemy.transform.position=front.transform.position+Vector3.up*.1f;w.NotifyUnitHit(enemy,"B",front);svc.Tick(.1f);Check(svc.Supporting(rear)&&svc.Supporting(third)&&rear.Motor.IsMoving,"enemy hit dispatches all connected helpers");svc.CancelDefense(rear);Check(svc.LinkCount(rear)==0&&!svc.Supporting(rear)&&svc.LinkCount(front)==1,"member cancels own links while other association survives");svc.CancelDefense(front);Check(svc.LinkCount(third)==0&&!svc.Supporting(third),"last association cancellation stops support");
  front.transform.position=p;rear.transform.position=q;svc.LinkDefense(front,rear);w.NotifyUnitHit(enemy,"B",front);svc.Tick(.1f);var revision=rear.Motor.ArrowOrderRevision;var service=w.GetComponent<BattleCommandService>();Check(service.Submit(new BattleCommand{playerId="A",unitId=rear.unitId,kind=BattleCommandKind.StopMovement}).accepted,"manual stop accepted");Check(!svc.Supporting(rear)&&!rear.Motor.IsMoving&&svc.LinkCount(rear)==1,"manual stop stops support while retaining defense link");w.NotifyUnitHit(enemy,"B",front);svc.Tick(.1f);Check(!svc.Supporting(rear)&&rear.Motor.ArrowOrderRevision==revision,"new support does not immediately override manual stop");svc.CancelDefense(rear);
  front.transform.position=p;rear.transform.position=q;var patrol=w.GetComponent<LocalPrototypeOrders>();Check(patrol.StartPatrol(rear,new[]{new LocalPrototypeOrders.Waypoint{position=q},new LocalPrototypeOrders.Waypoint{position=p}}),"patrol for support resume starts");svc.Tick(3);patrol.Tick(.1f);svc.LinkDefense(front,rear);w.NotifyUnitHit(enemy,"B",front);svc.Tick(.1f);Check(svc.Supporting(rear)&&!patrol.IsAssigned(rear),"support suspends original patrol");svc.Tick(7);Check(!svc.Supporting(rear)&&patrol.IsAssigned(rear),"quiet support completion resumes original patrol");svc.CancelDefense(front);patrol.CancelUnit(rear,true);
  new GameObject("coord network exclusion").AddComponent<LocalPvpSession>();Check(!svc.StartRotation(front,rear)&&!svc.LinkDefense(front,rear),"network client excludes new offline commands");LocalPvpSession.CloseActive();
 }
 static void Poll(){try{if(EditorApplication.timeSinceStartup-start>120)throw new Exception("timeout");if(!EditorApplication.isPlaying||Time.time<.7f)return;var w=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(w==null||!w.Initialized)return;Test(w);Finish(null);}catch(Exception e){Finish(e);}}
 static void Finish(Exception e){if(e!=null){rows.Add("FAIL "+e);Debug.LogException(e);}File.WriteAllText("C:/Users/ZWQ/Documents/Codex/2026-10-19/c-desktop-wargame-9/work/unit-actions-20261020/verification.txt",string.Join("\n",rows));SessionState.SetBool(Key,false);EditorApplication.update-=Poll;EditorApplication.Exit(e==null?0:1);}
}}
